<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway;

use Override;
use ArrayIterator;

use Civi\Lughauth\Features\Document\TemplateAsset\Domain\TemplateAsset;

/**
 * @template-extends ArrayIterator<int, TemplateAsset>
 */
class TemplateAssetSlide extends \ArrayIterator
{
  private readonly ?TemplateAsset $last;
  private readonly TemplateAssetCursor $nextCursor;
  public function __construct(
    private readonly ?\Closure $next,
    private readonly ?TemplateAssetCursor $cursor,
    private readonly array $values
  ) {
    parent::__construct($values);
    $this->last = $values ? end($values) : null;
    $cursor = $this->cursor;
    $last = $this->last;
    $this->nextCursor = new TemplateAssetCursor(
      limit: null === $cursor ? 1000 : $cursor->limit(),
      sinceUid: null == $last ? null : $last->uid(),
      sinceCode: null === $last ? null : $last->getCode(),
    );
  }
  public function cursor(): ?TemplateAssetCursor
  {
    return $this->cursor;
  }
  public function nextCursor(): TemplateAssetCursor
  {
    return $this->nextCursor;
  }
  public function values(): array
  {
    return $this->values;
  }
  #[Override]
  public function current(): ?TemplateAsset
  {
    return parent::current();
  }
  public function map(\Closure $fn): TemplateAssetSlide
  {
    return new TemplateAssetSlide($this->next, $this->cursor, array_map($fn, $this->values) );
  }
  public function slide(\Closure $fn): TemplateAssetSlide
  {
    $filtered = array_filter($this->values, $fn);
    $collected = $filtered;
    $last = $this->last;
    $next = $this->next;
    $cursor = $this->cursor;
    if (null !== $cursor && count($collected) == $cursor->limit()) {
      while (count($collected) < count($this->values) && $next !== null) {
        if ($last === null) {
          break;
        }
        $nextSlide = $next($this, $cursor->next($last, $cursor->limit()));
        if (count($nextSlide)) {
          $nextFiltered = array_filter($nextSlide->values, $fn);
          $collected = array_merge($collected, $nextFiltered);
          $cursor = $nextSlide->cursor;
          $next = $nextSlide->next;
          $last = $nextSlide->last;
        } else {
          break;
        }      }
      return new TemplateAssetSlide($next, $cursor, $collected);
    } else {
      return $this;
    }
  }
}
